      const config: SessionConfig = {
        name: "h3-idle",
        password: sessionConfig.password,
        idleTimeout: 60,
        generateId: () => `idle-${++idCtr}`,
      };
      t.app.get("/idle", async (event) => {
        const session = await useSession(event, config);

