  describe("lazy creation", () => {
    const lazyConfig: SessionConfig = {
      name: "h3-lazy",
      password: "1234567123456712345671234567123456712345671234567",
    };

    it("does not persist a session that is only read", async () => {
      t.app.get("/peek", async (event) => {
        const session = await getSession(event, lazyConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/peek");
      expect(res.headers.getSetCookie()).toHaveLength(0);
      expect(await res.json()).toMatchObject({ data: {} });
    });

    it("persists on the first write after a read", async () => {
      t.app.get("/login", async (event) => {
        await getSession(event, lazyConfig);
        const session = await updateSession(event, lazyConfig, { user: "alice" });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/login");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(res.headers.getSetCookie()[0]).toContain("h3-lazy=");
      expect(await res.json()).toMatchObject({ data: { user: "alice" } });
    });

    it("seals once when updateSession creates the session", async () => {
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      t.app.get("/seal-count", async (event) => {
        await updateSession(event, lazyConfig, { user: "alice" });
        return "ok";
      });

      deriveBits.mockClear();
      const res = await t.fetch("/seal-count");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      // Two derivations (encryption + integrity) for a single seal
      expect(deriveBits).toHaveBeenCalledTimes(2);
      deriveBits.mockRestore();
    });

    it("useSession still force-inits after a bare getSession", async () => {
      t.app.get("/peek-then-use", async (event) => {
        await getSession(event, lazyConfig); // e.g. auth middleware peeking
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res = await t.fetch("/peek-then-use");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("useSession still force-inits when read concurrently", async () => {
      t.app.get("/concurrent", async (event) => {
        const [, session] = await Promise.all([
          getSession(event, lazyConfig),
          useSession(event, lazyConfig),
        ]);
        return { id: session.id };
      });

      const res = await t.fetch("/concurrent");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("keeps the session id stable across requests once persisted", async () => {
      t.app.get("/stable", async (event) => {
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res1 = await t.fetch("/stable");
      const setCookie = res1.headers.getSetCookie()[0];
      const { id } = await res1.json();

      const res2 = await t.fetch("/stable", {
        headers: { Cookie: setCookie.split(";")[0] },
      });
      expect(await res2.json()).toMatchObject({ id });
    });
  });

  describe("password list", () => {
    const NEW_PASSWORD = "new-password-0123456789-abcdefghijk";
    const OLD_PASSWORD = "old-password-0123456789-abcdefghijk";
    const OTHER_PASSWORD = "other-password-0123456789-abcdefghi";
    const legacyDefaults = {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    };

    let listIdCtr = 0;
    const listConfig = (password: string | string[], extra?: Partial<SessionConfig>) =>
      ({
        name: "h3-test",
        password,
        generateId: () => `list-${++listIdCtr}`,
        ...extra,
      }) as SessionConfig;

    const sealedValue = (setCookie: string) =>
      decodeURIComponent(setCookie.match(/h3-test=([^;]+)/)![1]);

    const writeRoute = (config: SessionConfig) =>
      t.app.get("/write", async (event) => {
        await updateSession(event, config, { user: "alice" });
        return "ok";
      });

    const readRoute = (config: SessionConfig) =>
      t.app.get("/read", async (event) => {
        const session = await useSession(event, config);
        return { session };
      });

    it("seals with the first password only", async () => {
      writeRoute(listConfig([NEW_PASSWORD, OLD_PASSWORD]));

      const res = await t.fetch("/write");
      const sealed = sealedValue(res.headers.getSetCookie()[0]);
      expect(await unseal(sealed, NEW_PASSWORD, sealDefaults)).toMatchObject({
        data: { user: "alice" },
      });
      await expect(unseal(sealed, OLD_PASSWORD, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("reads a session sealed with an older password in the list", async () => {
      readRoute(listConfig([NEW_PASSWORD, OLD_PASSWORD]));
      const sealed = await seal(
        { id: "old", createdAt: Date.now(), data: { user: "bob" } },
        OLD_PASSWORD,
        sealDefaults,
      );

      const res = await t.fetch("/read", { headers: { Cookie: `h3-test=${sealed}` } });
      expect(await res.json()).toMatchObject({
        session: { id: "old", data: { user: "bob" } },
      });
    });

    it("treats a session sealed with a password outside the list as new", async () => {
      readRoute(listConfig([NEW_PASSWORD, OLD_PASSWORD]));
      const sealed = await seal(
        { id: "other", createdAt: Date.now(), data: { user: "eve" } },
        OTHER_PASSWORD,
        sealDefaults,
      );

      const res = await t.fetch("/read", { headers: { Cookie: `h3-test=${sealed}` } });
      expect(res.status).toBe(200);
      const body = await res.json();
      expect(body.session.id).not.toBe("other");
      expect(body.session.data).toEqual({});
    });

    it("rejects an empty password list", async () => {
      t.app.get("/empty", async (event) => {
        try {
          await updateSession(event, listConfig([]), { user: "alice" });
          return { message: "" };
        } catch (error) {
          return { message: (error as Error).message };
        }
      });

      const res = await t.fetch("/empty");
      expect(await res.json()).toMatchObject({
        message: "Session password list is empty",
      });
    });

    it("rejects a short password in the list on read and write", async () => {
      const config = listConfig([NEW_PASSWORD, "short"]);
      const sealed = await seal(
        { id: "new", createdAt: Date.now(), data: {} },
        NEW_PASSWORD,
        sealDefaults,
      );
      t.app.get("/short-read", async (event) => {
        try {
          await getSession(event, config);
          return { message: "" };
        } catch (error) {
          return { message: (error as Error).message };
        }
      });
      t.app.get("/short-write", async (event) => {
        try {
          await updateSession(event, config, { user: "alice" });
          return { message: "" };
        } catch (error) {
          return { message: (error as Error).message };
        }
      });

      const expected = { message: "Password string too short (min 32 characters required)" };
      const read = await t.fetch("/short-read", { headers: { Cookie: `h3-test=${sealed}` } });
      expect(await read.json()).toMatchObject(expected);
      const write = await t.fetch("/short-write", { headers: { Cookie: `h3-test=${sealed}` } });
      expect(await write.json()).toMatchObject(expected);
    });

    it("unseals a legacy session with the second password and reseals with the first", async () => {
      readRoute(listConfig([NEW_PASSWORD, OLD_PASSWORD]));
      const legacySealed = await seal(
        { id: "legacy", createdAt: Date.now(), data: { user: "carol" } },
        OLD_PASSWORD,
        legacyDefaults,
      );

      const res = await t.fetch("/read", { headers: { Cookie: `h3-test=${legacySealed}` } });
      expect(await res.json()).toMatchObject({
        session: { id: "legacy", data: { user: "carol" } },
      });

      const setCookies = res.headers.getSetCookie();
      expect(setCookies).toHaveLength(1);
      const resealed = sealedValue(setCookies[0]);
      expect(await unseal(resealed, NEW_PASSWORD, sealDefaults)).toMatchObject({
        id: "legacy",
        data: { user: "carol" },
      });
      await expect(unseal(resealed, OLD_PASSWORD, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("rejects a legacy session with the second password when legacySealFallback is false", async () => {
      t.app.get("/strict", async (event) => {
        const session = await useSession(
          event,
          listConfig([NEW_PASSWORD, OLD_PASSWORD], { legacySealFallback: false }),
        );
        return { session };
      });
      const legacySealed = await seal(
        { id: "legacy", createdAt: Date.now(), data: { user: "carol" } },
        OLD_PASSWORD,
        legacyDefaults,
      );

      const res = await t.fetch("/strict", { headers: { Cookie: `h3-test=${legacySealed}` } });
      const body = await res.json();
      expect(body.session.id).not.toBe("legacy");
      expect(body.session.data).toEqual({});
    });

    it("rewrites a session read with an older password using the first password", async () => {
      writeRoute(listConfig([NEW_PASSWORD, OLD_PASSWORD]));
      const oldSealed = await seal(
        { id: "old", createdAt: Date.now(), data: { user: "bob" } },
        OLD_PASSWORD,
        sealDefaults,
      );

      const res = await t.fetch("/write", { headers: { Cookie: `h3-test=${oldSealed}` } });
      const resealed = sealedValue(res.headers.getSetCookie()[0]);
      expect(await unseal(resealed, NEW_PASSWORD, sealDefaults)).toMatchObject({
        id: "old",
        data: { user: "alice" },
      });
      await expect(unseal(resealed, OLD_PASSWORD, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("documents the derivation cost of reading with the second password", async () => {
      readRoute(listConfig([NEW_PASSWORD, OLD_PASSWORD]));
      const oldSealed = await seal(
        { id: "old", createdAt: Date.now(), data: {} },
        OLD_PASSWORD,
        sealDefaults,
      );

      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      deriveBits.mockClear();
      await t.fetch("/read", { headers: { Cookie: `h3-test=${oldSealed}` } });
      // NEW: one HMAC key (fails). OLD: one HMAC key, then one decryption key.
      expect(deriveBits).toHaveBeenCalledTimes(3);
      deriveBits.mockRestore();
    });
  });
});

